aside{grid-column:1;grid-row:2;border-right:1px solid var(--line);padding:34px 24px 26px;position:fixed;top:72px;bottom:0;width:238px;display:flex;flex-direction:column}.nav-label{font-size:10px;text-transform:uppercase;letter-spacing:1.5px;font-weight:700;color:#9b9b93;margin:0 0 9px 11px}.nav-label.space{margin-top:31px}nav button{width:100%;border:0;background:transparent;min-height:39px;border-radius:8px;padding:0 11px;display:flex;align-items:center;gap:11px;text-align:left;font-size:13px;cursor:pointer;color:#53605b}nav button:hover{background:#ece8dd}nav button.active{background:#e3e6db;color:#1e3930;font-weight:600}nav button b{margin-left:auto;font-size:11px;font-weight:500;color:#9b9d96}.unread-dot,.collection-dot{width:8px;height:8px;background:#e16b45;border-radius:50%;margin:0 5px}.collection-dot{background:#6f9685}.c1{background:#d28d64}.c2{background:#71879c}.c3{background:#a77e99}.c4{background:#bd9a52}.c5{background:#7b9675}.aside-card{margin-top:auto;border-top:1px solid var(--line);padding:22px 9px 9px;display:flex;gap:10px;color:#747b76}.aside-card>span{color:#d77950}.aside-card p{font:12px/1.55 'DM Sans';margin:0}.aside-card strong{color:#4d5954}.aside-footer{font-size:10px;color:#a2a29b;margin:12px 9px 0}
main{grid-column:2;grid-row:2;padding:58px clamp(34px,5vw,78px) 80px;max-width:1480px;width:100%;margin:auto}.hero{max-width:675px}.eyebrow{text-transform:uppercase;letter-spacing:2.1px;font-size:10px;font-weight:700;color:#d35f3d;margin:0 0 14px}.hero h1{font:400 clamp(40px,5vw,65px)/1.03 'DM Serif Display',serif;letter-spacing:-2px;margin:0;color:#1f332d}.hero h1 em{font-weight:400;color:#d56543}.intro{color:#75807b;max-width:530px;font-size:14px;line-height:1.7;margin:18px 0 0}.toolbar{margin:47px 0 19px;padding-top:17px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.toolbar p{font-size:11px;color:#959994;margin:0;text-transform:uppercase;letter-spacing:.7px}.toolbar p strong{color:#52605a}.toolbar p span{margin:0 6px}.view-toggle{display:flex;border:1px solid #d7d2c7;border-radius:7px;padding:2px}.view-toggle button{border:0;background:transparent;width:31px;height:27px;border-radius:5px;display:grid;place-items:center;color:#9b9b93;cursor:pointer}.view-toggle button.selected{background:white;color:#31483f;box-shadow:0 1px 4px rgba(0,0,0,.08)}
.bookmark-list.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.bookmark-card{background:#f9f7f1;border:1px solid #ddd8cd;border-radius:12px;min-height:268px;padding:20px;display:flex;flex-direction:column;position:relative;animation:rise .45s both;animation-delay:var(--delay);transition:transform .2s,box-shadow .2s,border-color .2s}.bookmark-card:hover{transform:translateY(-3px);box-shadow:0 13px 30px rgba(52,55,45,.08);border-color:#cec7ba}@keyframes rise{from{opacity:0;transform:translateY(9px)}to{opacity:1;transform:translateY(0)}}.card-head{display:flex;align-items:center;position:relative}.site-icon{width:34px;height:34px;border-radius:8px;color:white;display:grid;place-items:center;font:600 15px 'DM Serif Display'}.site-meta{display:flex;flex-direction:column;margin-left:10px;min-width:0}.site-meta span{font-size:11px;color:#59645f;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:115px}.site-meta small{color:#aaa9a0;font-size:9px;margin-top:2px}.star,.more{border:0;background:none;width:28px;height:28px;display:grid;place-items:center;color:#b0afa7;cursor:pointer;border-radius:6px;padding:0}.star{margin-left:auto}.star.on{color:#e47a48}.star:hover,.more:hover{background:#eeeae1;color:#59655f}.card-body{margin-top:22px}.card-body h2{font:400 20px/1.2 'DM Serif Display';margin:0;color:#243831}.card-body h2 a{text-decoration:none;color:inherit}.open-icon{opacity:0;margin-left:4px;transform:translate(-3px,3px);transition:.2s}.card-body h2 a:hover .open-icon{opacity:1;transform:none}.card-body p{font-size:12px;color:#78807c;line-height:1.55;margin:10px 0 0;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.card-foot{display:flex;align-items:center;justify-content:space-between;margin-top:auto;padding-top:18px}.card-foot>div{display:flex;gap:5px;min-width:0;overflow:hidden}.card-foot button{border:0;background:none;cursor:pointer}.card-foot>div button{font-size:9px;background:#ece9df;color:#78807a;padding:4px 7px;border-radius:10px}.read-status{font-size:9px;color:#9b9d97;white-space:nowrap}.read-status.done{color:#4f7467;display:flex;align-items:center;gap:3px}.card-menu{position:absolute;right:0;top:34px;background:white;border:1px solid #ddd8cc;border-radius:8px;padding:5px;z-index:5;width:105px;box-shadow:0 8px 22px rgba(37,45,40,.14)}.card-menu button{width:100%;display:flex;align-items:center;gap:7px;border:0;background:none;padding:8px;border-radius:5px;font-size:11px;text-align:left;cursor:pointer}.card-menu button:hover{background:#f1eee6}.card-menu button:last-child{color:#c65340}
